CREATE TABLE rate_policy_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,property_id uuid NOT NULL,version integer NOT NULL CHECK(version>0),effective_at timestamptz NOT NULL,base_rent bigint NOT NULL CHECK(base_rent BETWEEN 0 AND 1000000000000),config jsonb NOT NULL CHECK(jsonb_typeof(config)='object'),actor_id uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(organization_id,property_id,id),UNIQUE(organization_id,property_id,version),FOREIGN KEY(organization_id,property_id) REFERENCES properties(organization_id,id));
CREATE INDEX rate_effective ON rate_policy_versions(organization_id,property_id,effective_at DESC,version DESC);
CREATE TABLE policy_type_rates(organization_id uuid NOT NULL,property_id uuid NOT NULL,policy_id uuid NOT NULL,type_id uuid NOT NULL,amount bigint NOT NULL CHECK(amount BETWEEN 0 AND 1000000000000),PRIMARY KEY(policy_id,type_id),FOREIGN KEY(organization_id,property_id,policy_id) REFERENCES rate_policy_versions(organization_id,property_id,id),FOREIGN KEY(organization_id,property_id,type_id) REFERENCES room_types(organization_id,property_id,id));
CREATE TABLE policy_room_rates(organization_id uuid NOT NULL,property_id uuid NOT NULL,policy_id uuid NOT NULL,room_id uuid NOT NULL,amount bigint NOT NULL CHECK(amount BETWEEN 0 AND 1000000000000),PRIMARY KEY(policy_id,room_id),FOREIGN KEY(organization_id,property_id,policy_id) REFERENCES rate_policy_versions(organization_id,property_id,id),FOREIGN KEY(organization_id,property_id,room_id) REFERENCES rooms(organization_id,property_id,id));
CREATE TABLE pricing_quotes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,property_id uuid NOT NULL,room_id uuid NOT NULL,policy_id uuid NOT NULL,actor_id uuid NOT NULL REFERENCES users(id),request jsonb NOT NULL,snapshot jsonb NOT NULL,expires_at timestamptz NOT NULL DEFAULT now()+interval '15 minutes',created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(organization_id,property_id,room_id) REFERENCES rooms(organization_id,property_id,id),FOREIGN KEY(organization_id,property_id,policy_id) REFERENCES rate_policy_versions(organization_id,property_id,id));
CREATE FUNCTION can_read_pricing(org uuid,location uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $$SELECT org=public.current_org() AND public.can_access_location(org,location) AND EXISTS(SELECT 1 FROM public.memberships m WHERE m.organization_id=org AND m.user_id=public.current_actor() AND m.revoked_at IS NULL AND m.role IN ('Owner','Manager','Finance'))$$;
REVOKE ALL ON FUNCTION can_read_pricing(uuid,uuid) FROM PUBLIC;GRANT EXECUTE ON FUNCTION can_read_pricing(uuid,uuid) TO kost_app;
DO $$DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['rate_policy_versions','policy_type_rates','policy_room_rates','pricing_quotes'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t);EXECUTE format('CREATE POLICY pricing_read ON %I FOR SELECT TO kost_app USING(can_read_pricing(organization_id,property_id))',t);EXECUTE format('CREATE POLICY pricing_insert ON %I FOR INSERT TO kost_app WITH CHECK(can_manage_inventory(organization_id,property_id))',t);END LOOP;END $$;
CREATE FUNCTION guard_policy_version() RETURNS trigger LANGUAGE plpgsql AS $$DECLARE previous integer;BEGIN PERFORM pg_advisory_xact_lock(hashtextextended('pricing:'||NEW.organization_id::text||':'||NEW.property_id::text,0));SELECT coalesce(max(version),0) INTO previous FROM rate_policy_versions WHERE organization_id=NEW.organization_id AND property_id=NEW.property_id;IF NEW.version<>previous+1 THEN RAISE EXCEPTION 'VERSION_CONFLICT' USING ERRCODE='P0409';END IF;IF NEW.actor_id IS DISTINCT FROM current_actor() THEN RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE='P0403';END IF;RETURN NEW;END $$;
CREATE TRIGGER policy_version_guard BEFORE INSERT ON rate_policy_versions FOR EACH ROW EXECUTE FUNCTION guard_policy_version();
CREATE POLICY quote_actor ON pricing_quotes AS RESTRICTIVE FOR SELECT TO kost_app USING(actor_id=current_actor());
CREATE POLICY quote_actor_insert ON pricing_quotes AS RESTRICTIVE FOR INSERT TO kost_app WITH CHECK(actor_id=current_actor());
GRANT SELECT,INSERT ON rate_policy_versions,policy_type_rates,policy_room_rates,pricing_quotes TO kost_app;
